/*
	VIOC_ai_air_support.sqf - agregado por tools/vio_build.py (parche ai_air_support; no es del autor de la mision).
	Fuente: work/v6_build/ai_air_support/.

	La IA de un bando SIN jugadores humanos (p. ej. Rusia contra ti) pide el mismo apoyo aereo que los jugadores:
	avion de ataque (A-10 / Su-25), Ghostrider (si su nacion lo tiene; Rusia no) y helicopteros de ataque (Apache /
	Mi-28N / Ka-52 / Mi-24). Con las MISMAS reglas, porque todo pasa por VIOC_AS_fnc_requestDo
	(VIOC_air_support_server.sqf) con _ai = true:
	  - mismo precio; lo paga el comandante IA con sus fondos y guarda su reserva (VIOC_fnc_soPayer de VIOC_specops.sqf,
	    como las operaciones especiales); si el comandante es humano, el equipo IA mas rico;
	  - misma espera por bando y tipo, uno de cada tipo a la vez por bando, mismo presupuesto de IA;
	  - mismas distancias de seguridad a SUS tropas (75 m; 100 m con bombas; 40 m helicopteros);
	  - se les puede derribar igual (y si caen, la espera larga); si el ataque no sale, se le devuelve el dinero.
	Cuando: cada VIOC_AAS_TICK s busca un grupo de un bando humano en contacto (a menos de VIOC_AAS_CONTACT m de un pueblo
	propio o de tropas propias) con VIOC_AAS_MINMEN o mas hombres a pie, o algun blindado, a menos de VIOC_AAS_CLUSTER m.
	Probabilidad VIOC_AAS_CHANCE por oportunidad, minimo VIOC_AAS_GAP s entre dos pedidos del bando, nunca antes de
	VIOC_AAS_START s de partida.
	Que pide: con blindados, el avion (bombas guiadas, mixto, cohetes o canon); con mucha infanteria (VIOC_AAS_HELIMEN+),
	los helicopteros; si no, el Ghostrider o lo que quede libre.
	No en la mision B (Colombia): alli solo puede pedirlo el bando de Colombia (la narcoinsurgencia no tiene aviacion).
	Solo servidor. Lobby: VIOC_AI_AIR_SUPPORT (0 no / 1 si).
	Consola (servidor; en partida alojada vale "Ejecucion local"): hint (call VIOC_AAS_fnc_info);
*/
if (!isServer) exitWith {};
if (!isNil "VIOC_AAS_STARTED") exitWith {};
VIOC_AAS_STARTED = true;

//--- revision: quien paga y bandos humanos sin depender de VIOC_specops.sqf (que sale antes si las operaciones especiales
//--- estan apagadas en el lobby). Se definen siempre: VIOC_AS_fnc_requestDo y VIOC_AS_fnc_refund las usan.
VIOC_AAS_HUMANS = [];
VIOC_AAS_fnc_humans = {
	if (!isNil "VIOC_fnc_soHumanSides") exitWith {call VIOC_fnc_soHumanSides};
	private _pl = allPlayers - (entities "HeadlessClient_F");
	if (!isMultiplayer && {hasInterface} && {!isNull player}) then {_pl pushBackUnique player};
	{private _s = side group _x; if (_s in [west, east]) then {VIOC_AAS_HUMANS pushBackUnique _s}} forEach _pl;
	VIOC_AAS_HUMANS
};
//--- [tipo de pagador, grupo] o [] (comandante IA con reserva de 5000, como las operaciones especiales)
VIOC_AAS_fnc_payer = {
	params ["_side", "_price"];
	if (!isNil "VIOC_fnc_soPayer") exitWith {[_side, _price] call VIOC_fnc_soPayer};
	private _f = _side call CTI_CO_FNC_GetFundsCommander;
	if (!isNil "_f" && {_f isEqualType 0} && {_f >= (_price + 5000)}) then {["commander", grpNull]} else {[]}
};
VIOC_AAS_fnc_charge = {
	params ["_side", "_payer", "_amount"];
	if (!isNil "VIOC_fnc_soCharge") exitWith {[_side, _payer, _amount] call VIOC_fnc_soCharge};
	if (count _payer > 0 && {(_payer select 0) == "commander"}) then {[_side, _amount] call CTI_CO_FNC_ChangeFundsCommander};
};

VIOC_AAS_MODE = missionNamespace getVariable ["VIOC_AI_AIR_SUPPORT", 1];
if !(VIOC_AAS_MODE isEqualType 0) then {VIOC_AAS_MODE = 1};
if (VIOC_AAS_MODE <= 0) exitWith {};

VIOC_AAS_START = 600;		//--- s de partida antes del primer pedido
VIOC_AAS_TICK = 30;			//--- s entre dos miradas
VIOC_AAS_GAP = 240;			//--- s minimos entre dos pedidos del mismo bando (aparte de la espera de cada tipo)
VIOC_AAS_CHANCE = 0.5;		//--- probabilidad de pedir en cada oportunidad (si no, otra mirada en 60 s)
VIOC_AAS_CONTACT = 800;		//--- m: en contacto = a menos de esto de un pueblo propio o de tropas propias
VIOC_AAS_CLUSTER = 150;		//--- m alrededor del jefe del grupo enemigo donde se cuentan los blancos
VIOC_AAS_MINMEN = 5;		//--- hombres a pie minimos (o un blindado)
VIOC_AAS_HELIMEN = 6;		//--- con tantos hombres a pie o mas, helicopteros
VIOC_AAS_NEXT = [0, 0];		//--- [oeste, este]: time desde el que puede volver a pedir
VIOC_AAS_LAST = ["", ""];
VIOC_AAS_N = [0, 0];

VIOC_AAS_fnc_log = {diag_log format ["[VIOC ai_air_support] %1", _this]};

//--- true si la IA de ese bando puede pedir: sin jugadores humanos (nunca los tuvo) y no es la narcoinsurgencia.
VIOC_AAS_fnc_sideOk = {
	params ["_side"];
	if (isNil "VIOC_ASS_MODE" || {VIOC_ASS_MODE <= 0}) exitWith {false};
	if (_side in (call VIOC_AAS_fnc_humans)) exitWith {false};
	private _col = missionNamespace getVariable ["CTI_COL_SIDE", -1];
	if ((_col isEqualType 0) && {_col >= 0} && {!((_col call CTI_CO_FNC_GetSideFromID) isEqualTo _side)}) exitWith {false};
	true
};

//--- Mejor blanco: [posicion, hombres a pie, vehiculos, blindados] o [].
VIOC_AAS_fnc_target = {
	params ["_side"];
	private _hs = (call VIOC_AAS_fnc_humans) select {(_side getFriend _x) < 0.6};
	if (count _hs == 0) exitWith {[]};
	private _sid = _side call CTI_CO_FNC_GetSideID;
	private _myTowns = (missionNamespace getVariable ["CTI_Towns", []]) select {(_x getVariable ["cti_town_sideID", -1]) == _sid};
	private _best = [];
	private _bs = 0;
	{
		private _l = leader _x;
		if (((side _x) in _hs) && {alive _l}) then {
			private _v = vehicle _l;
			private _p = getPosATL _v;
			if (!(_v isKindOf "Air") && {!(_v isKindOf "Ship")} && {!surfaceIsWater _p}) then {
				private _contact = (_myTowns findIf {(_x distance2D _p) < VIOC_AAS_CONTACT}) >= 0;
				if (!_contact) then {
					_contact = ((_p nearEntities [["CAManBase", "LandVehicle", "StaticWeapon"], VIOC_AAS_CONTACT]) findIf {
						alive _x && {(if (_x isKindOf "CAManBase") then {side group _x} else {side _x}) == _side}
					}) >= 0;
				};
				if (_contact) then {
					private _ents = _p nearEntities [["CAManBase", "LandVehicle"], VIOC_AAS_CLUSTER];
					private _men = _ents select {(_x isKindOf "CAManBase") && {alive _x} && {(side group _x) in _hs}};
					private _veh = _ents select {!(_x isKindOf "CAManBase") && {alive _x} && {({alive _x} count (crew _x)) > 0} && {(side _x) in _hs}};
					private _arm = {(_x isKindOf "Tank") || {_x isKindOf "Wheeled_APC_F"}} count _veh;
					private _sc = (count _men) + 3 * (count _veh) + 3 * _arm;
					if (((count _men) >= VIOC_AAS_MINMEN || {_arm > 0}) && {_sc > _bs}) then {
						private _all = _men + _veh;
						private _cx = 0;
						private _cy = 0;
						{private _q = getPosATL _x; _cx = _cx + (_q select 0); _cy = _cy + (_q select 1)} forEach _all;
						private _c = [_cx / (count _all), _cy / (count _all), 0];
						if (surfaceIsWater _c) then {_c = [_p select 0, _p select 1, 0]};
						_bs = _sc;
						_best = [_c, count _men, count _veh, _arm];
					};
				};
			};
		};
	} forEach allGroups;
	_best
};

//--- true si el bando tiene ese tipo (0 avion, 1 Ghostrider, 2 helicopteros), libre y sin espera.
VIOC_AAS_fnc_avail = {
	params ["_side", "_k"];
	private _si = [west, east] find _side;
	if (_si < 0) exitWith {false};
	private _cls = (VIOC_ASS_CLASS param [_k, []]) param [_si, ""];
	if !(_cls isEqualType "") exitWith {false};
	if (_cls == "") exitWith {false};
	private _kind = ["cas", "gs", "heli"] select _k;
	if ((VIOC_ASS_ACTIVE findIf {((_x get "kind") == _kind) && {(_x get "side") == _side}}) >= 0) exitWith {false};
	(([_kind, _side] call VIOC_AS_fnc_cdLeft) select 0) <= 0
};

//--- Que pedir, por orden de preferencia: [[tipo, modo del avion], ...] (revision: si el primero no sale, se prueba el siguiente).
VIOC_AAS_fnc_pick = {
	params ["_side", "_men", "_arm"];
	private _modes = VIOC_ASS_MODES param [[west, east] find _side, []];
	private _mode = {
		params ["_pref"];
		private _m = -1;
		{if (_m < 0 && {(_modes param [_x, false]) isEqualTo true}) then {_m = _x}} forEach _pref;
		_m max 0
	};
	private _order = if (_arm > 0) then {[["cas", [[2, 3, 1, 0]] call _mode], ["heli", 0], ["gs", 0], ["cas", [[3, 1, 0]] call _mode]]} else {
		if (_men >= VIOC_AAS_HELIMEN) then {[["heli", 0], ["gs", 0], ["cas", [[3, 1, 0, 2]] call _mode]]} else {[["gs", 0], ["cas", [[3, 1, 0, 2]] call _mode], ["heli", 0]]}
	};
	private _l = [];
	{
		private _k = ["cas", "gs", "heli"] find (_x select 0);
		if (([_side, _k] call VIOC_AAS_fnc_avail) && {!(_x in _l)}) then {_l pushBack _x};
	} forEach _order;
	_l
};

//--- Unidad IA viva del bando que "firma" el pedido (jefe del grupo del comandante IA o de otro grupo IA).
VIOC_AAS_fnc_proxy = {
	params ["_side"];
	private _u = objNull;
	private _logic = _side call CTI_CO_FNC_GetSideLogic;
	if (!isNil "_logic" && {_logic isEqualType objNull} && {!isNull _logic}) then {
		private _cmd = _logic getVariable ["cti_commander", grpNull];
		if ((_cmd isEqualType grpNull) && {!isNull _cmd} && {alive (leader _cmd)} && {!isPlayer (leader _cmd)}) then {_u = leader _cmd};
	};
	if (isNull _u) then {
		private _gs = _side call CTI_CO_FNC_GetSideGroups;
		if (isNil "_gs" || {!(_gs isEqualType [])}) then {_gs = []};
		{
			if (isNull _u && {_x isEqualType grpNull} && {!isNull _x} && {(side _x) == _side} && {alive (leader _x)} && {!isPlayer (leader _x)}) then {_u = leader _x};
		} forEach _gs;
	};
	_u
};

//--- Consola: estado.
VIOC_AAS_fnc_info = {
	format ["Apoyo aereo de la IA: activo %1. Pedidos: oeste %2 / este %3. Puede: oeste %4 / este %5. Ultimo oeste: %6. Ultimo este: %7.",
		VIOC_AAS_MODE, VIOC_AAS_N select 0, VIOC_AAS_N select 1, [west] call VIOC_AAS_fnc_sideOk, [east] call VIOC_AAS_fnc_sideOk, VIOC_AAS_LAST select 0, VIOC_AAS_LAST select 1]
};

[] spawn {
	waitUntil {sleep 5; !isNil "CTI_Init_Server" && {!isNil "VIOC_AS_CFG"}};
	waitUntil {sleep 10; time > VIOC_AAS_START};
	"activo" call VIOC_AAS_fnc_log;
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		sleep VIOC_AAS_TICK;
		isNil {call VIOC_AS_fnc_prune};	//--- revision: un registro colgado no bloquea a la IA
		{
			private _side = _x;
			private _i = _forEachIndex;
			//--- revision: antes de buscar blancos (caro), que haya algun tipo libre y con que pagar el mas barato
			private _ks = [0, 1, 2] select {[_side, _x] call VIOC_AAS_fnc_avail};
			private _cheap = if (count _ks > 0) then {selectMin (_ks apply {[VIOC_ASS_CAS_PRICE, VIOC_ASS_GS_PRICE, VIOC_ASS_HA_PRICE] select _x})} else {0};
			if ((time >= (VIOC_AAS_NEXT select _i)) && {count _ks > 0} && {[_side] call VIOC_AAS_fnc_sideOk} && {count ([_side, _cheap] call VIOC_AAS_fnc_payer) > 0}) then {
				private _t = [_side] call VIOC_AAS_fnc_target;
				if (count _t > 0) then {
					_t params ["_pos", "_men", "_veh", "_arm"];
					private _pks = [_side, _men, _arm] call VIOC_AAS_fnc_pick;
					if (count _pks > 0) then {
						if (random 1 < VIOC_AAS_CHANCE) then {
							private _u = [_side] call VIOC_AAS_fnc_proxy;
							if (!isNull _u) then {
								private _r = "?";
								private _done = [];
								{
									private _pk = _x;
									if (_r != "ok") then {
										//--- revision: sin interrupciones, como el pedido de un jugador (remoteExecCall)
										isNil {_r = [_u, _pk select 0, _pos, _pk select 1, -1, false, false, true] call VIOC_AS_fnc_requestDo};
										if (isNil "_r" || {!(_r isEqualType "")}) then {_r = "?"};
										_done pushBack format ["%1: %2", _pk select 0, _r];
									};
								} forEach _pks;
								VIOC_AAS_LAST set [_i, format ["%1 s sobre %2 (%3 hombres, %4 vehiculos, %5 blindados): %6", round time, mapGridPosition _pos, _men, _veh, _arm, _done joinString " / "]];
								format ["%1 %2", _side, VIOC_AAS_LAST select _i] call VIOC_AAS_fnc_log;
								if (_r == "ok") then {
									VIOC_AAS_N set [_i, (VIOC_AAS_N select _i) + 1];
									VIOC_AAS_NEXT set [_i, time + VIOC_AAS_GAP];
								} else {VIOC_AAS_NEXT set [_i, time + 60]};
							};
						} else {VIOC_AAS_NEXT set [_i, time + 60]};
					};
				};
			};
		} forEach [west, east];
	};
};

params ["_uid", "_text", ["_data", []]];
if ((_uid select [0, 3]) == "ai:") exitWith {};	//--- v4: pedido de la IA (en "Un jugador" findPlayer daria el jugador)
private _p = [_uid] call VIOC_AS_fnc_findPlayer;

private _py = [];
if (_ai) then {
	//--- v4: paga el comandante IA (o el equipo IA mas rico) y guarda su reserva, como las operaciones especiales
	_py = [_side, _price] call VIOC_AAS_fnc_payer;
	_funds = if (count _py > 0) then {_price} else {-1};
} else {
	_funds = [_grp, _side] call CTI_CO_FNC_GetFunds;
	if (isNil "_funds" || {!(_funds isEqualType 0)}) then {_funds = 0};
};

call compile preprocessFileLineNumbers "VIOC_heli_attack.sqf";

//--- v4 ai_air_support: la IA de un bando sin jugadores pide el mismo apoyo (VIOC_AAS_fnc_*; parametro VIOC_AI_AIR_SUPPORT)
call compile preprocessFileLineNumbers "VIOC_ai_air_support.sqf";

class VIOC_AI_AIR_SUPPORT {
	title = "VIOC: Apoyo aereo de la IA (el bando sin jugadores pide avion de ataque, Ghostrider y helicopteros con los mismos precios, esperas y limites que tu)";
	values[] = {0,1};
	texts[] = {"No","Si"};
	default = 1;
};
